
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_revssb_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_revssb_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.527185364334532e+00, -4.438300064106259e+00, -4.314102743861797e+00, -4.142852338363587e+00, -3.911336117737195e+00, -3.607537887769036e+00, -3.226694958166497e+00, -2.780833676843833e+00, -2.301486591627180e+00, -1.811755479233592e+00, -1.247032165464421e+00, -7.486444247457066e-01, -6.360184977397763e-01, -5.160941645324357e-01, -3.774318173816055e-01, -2.460578617018300e-01, -1.336446198342893e-01, -4.951822280276920e-02, -1.081185421394320e-02, -1.216201563273550e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


